from __future__ import annotations

import json


def decode(body: bytes | memoryview[int]) -> object:
    return json.loads(bytes(body))


assert decode(b'{"status":499}') == {"status": 499}
assert decode(memoryview(b'{"status":599}')) == {"status": 599}
print('Both bytes and memoryview inputs decode correctly.')
